window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["terraform-09-terraform-br-level-1-2"]={"html":"\r\n\r\nTerraform Level 1+2 · Vol 1 · INK &amp; AMBER\r\n\r\n<div class=\"sheet cover\"><div class=\"stamp\">🏗️</div><div class=\"ckick\">Terraform Study Series · Volume One</div><h1 id=\"terraformlevel-1-2\">Terraform<br />Level 1 + 2</h1><div class=\"ambrule\"></div><p>The complete <b>beginner-to-intermediate</b> guide: Infrastructure as Code, the core workflow, AWS provider setup, networking, compute, remote state — and the Day 2 patterns that turn a script into a team tool. Built on the course deck by <b>Eng. Mohamed Magdy</b>.</p><div class=\"vols\"><div class=\"volcard\">Part I · Day 1<small>Foundations · Workflow · State</small></div><div class=\"volcard\">Part II · Day 2<small>Variables · Workspaces · HCL</small></div><div class=\"volcard\">Part III · L2<small>Provisioners · Modules · Capstone</small></div></div><div class=\"cver\">INK &amp; AMBER EDITION · 2026</div><div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 1 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">CONTENTS</div><h1 id=\"map-of-the-book\">🗺️ Map of the Book</h1></div><span class=\"hmeta\">☑ tick as you go</span></div></div>\r\n<p>Every page is a clickable door. Use the <b>TOC</b> badge at the bottom of every page to return here. Read the <a href=\"#summary\">Executive Summary</a> first — it tells the whole story in one page.</p>\r\n<div class=\"tocgrid\">\r\n<a href=\"#summary\"><span class=\"tnum\">→</span><span class=\"tp\">Executive Summary — The Route</span><span class=\"dots\"></span><span class=\"tp\">3</span></a>\r\n<a href=\"#ch-01\"><span class=\"tnum\">01</span><span class=\"tp\">What is Infrastructure as Code?</span><span class=\"dots\"></span><span class=\"tp\">4</span></a>\r\n<a href=\"#ch-02\"><span class=\"tnum\">02</span><span class=\"tp\">What is Terraform + Why (6 pillars)</span><span class=\"dots\"></span><span class=\"tp\">5</span></a>\r\n<a href=\"#ch-03\"><span class=\"tnum\">03</span><span class=\"tp\">How Terraform Works — Core vs Plugins</span><span class=\"dots\"></span><span class=\"tp\">6</span></a>\r\n<a href=\"#ch-04\"><span class=\"tnum\">04</span><span class=\"tp\">AWS Provider — Three Auth Patterns</span><span class=\"dots\"></span><span class=\"tp\">7</span></a>\r\n<a href=\"#ch-05\"><span class=\"tnum\">05</span><span class=\"tp\">Your First Resource — aws_vpc</span><span class=\"dots\"></span><span class=\"tp\">8</span></a>\r\n<a href=\"#ch-06\"><span class=\"tnum\">06</span><span class=\"tp\">VPC Networking — Subnets, IGW, NAT</span><span class=\"dots\"></span><span class=\"tp\">9</span></a>\r\n<a href=\"#ch-07\"><span class=\"tnum\">07</span><span class=\"tp\">terraform init — what it really does</span><span class=\"dots\"></span><span class=\"tp\">10</span></a>\r\n<a href=\"#ch-08\"><span class=\"tnum\">08</span><span class=\"tp\">plan · apply · tfstate — the core loop</span><span class=\"dots\"></span><span class=\"tp\">11</span></a>\r\n<a href=\"#ch-09\"><span class=\"tnum\">09</span><span class=\"tp\">The 3-State Model — code · state · reality</span><span class=\"dots\"></span><span class=\"tp\">12</span></a>\r\n<a href=\"#ch-10\"><span class=\"tnum\">10</span><span class=\"tp\">State Risks &amp; Remote Backend</span><span class=\"dots\"></span><span class=\"tp\">13</span></a>\r\n<a href=\"#ch-11\"><span class=\"tnum\">11</span><span class=\"tp\">State Locking — the mutex</span><span class=\"dots\"></span><span class=\"tp\">14</span></a>\r\n<a href=\"#ch-12\"><span class=\"tnum\">12</span><span class=\"tp\">State Subcommands &amp; CLI extras</span><span class=\"dots\"></span><span class=\"tp\">15</span></a>\r\n<a href=\"#ch-13\"><span class=\"tnum\">13</span><span class=\"tp\">fmt &amp; destroy — canon &amp; teardown</span><span class=\"dots\"></span><span class=\"tp\">16</span></a>\r\n<a href=\"#ch-14\"><span class=\"tnum\">14</span><span class=\"tp\">Variables &amp; the precedence ladder</span><span class=\"dots\"></span><span class=\"tp\">17</span></a>\r\n<a href=\"#ch-15\"><span class=\"tnum\">15</span><span class=\"tp\">Workspaces &amp; Advanced HCL</span><span class=\"dots\"></span><span class=\"tp\">18</span></a>\r\n<a href=\"#ch-16\"><span class=\"tnum\">16</span><span class=\"tp\">Outputs — share, export, CI/CD</span><span class=\"dots\"></span><span class=\"tp\">19</span></a>\r\n<a href=\"#ch-17\"><span class=\"tnum\">17</span><span class=\"tp\">Providers catalog — IaaS / PaaS / SaaS</span><span class=\"dots\"></span><span class=\"tp\">20</span></a>\r\n<a href=\"#ch-18\"><span class=\"tnum\">18</span><span class=\"tp\">Provisioners — doctrine: last resort</span><span class=\"dots\"></span><span class=\"tp\">21</span></a>\r\n<a href=\"#ch-19\"><span class=\"tnum\">19</span><span class=\"tp\">Modules — package, version, reuse</span><span class=\"dots\"></span><span class=\"tp\">22</span></a>\r\n<a href=\"#lab-1\"><span class=\"tnum\">★</span><span class=\"tp\">CAPSTONE — full build chain</span><span class=\"dots\"></span><span class=\"tp\">23</span></a>\r\n<a href=\"#cheat\"><span class=\"tnum\">▣</span><span class=\"tp\">Cheat · Quiz · Glossary · Resources</span><span class=\"dots\"></span><span class=\"tp\">24</span></a>\r\n</div>\r\n<h3 id=\"how-to-read-this-book\"><span class=\"n\">▣</span>How to read this book</h3>\r\n<ul>\r\n<li>🟢 <b>Concept pages</b> — read in order on Day 1.</li>\r\n<li>🟡 <b>Mechanics</b> — when you want to understand what plan/apply/state actually do.</li>\r\n<li>🟠 <b>Labs</b> — you need a terminal and 30 minutes.</li>\r\n<li>🖨 <b>Print the cheat page</b> — review card before any interview.</li>\r\n</ul>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 2 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">EXECUTIVE SUMMARY</div><h1 id=\"the-route-one-page-whole-book\">🗺️ The Route — One Page, Whole Book</h1></div><span class=\"hmeta\">📖 read first</span></div></div>\r\n<p>We begin with <b>why</b> clicking through consoles doesn't scale, and meet the contractor who fixes it. From there you learn to draw blueprints: <a href=\"#ch-04\">AWS provider</a> brings the keys (without exposing them); <a href=\"#ch-05\">your first VPC</a> draws the boundary. The book's beating heart: <a href=\"#ch-09\">state</a>, the ledger that remembers every resource, guarded by the <a href=\"#ch-08\">plan</a>, the dress rehearsal.</p>\r\n<p>Day 1 builds the foundation: <a href=\"#ch-07\">init</a> wires plugins, <a href=\"#ch-08\">plan/apply</a> executes the diff, <a href=\"#ch-10\">remote backend</a> stores the ledger, <a href=\"#ch-11\">locking</a> prevents collisions. By the end of Day 1 you've built a VPC, subnets, gateways, and a working EC2 with a security group — the whole cloud story in one sitting.</p>\r\n<p>Day 2 turns the one-off script into a team tool: <a href=\"#ch-14\">variables</a> parameterize inputs, <a href=\"#ch-15\">workspaces</a> isolate state per env, <a href=\"#ch-15\">count &amp; for_each</a> build N copies, <a href=\"#ch-16\">outputs</a> export values for CI/CD and other modules. One config, many environments, zero duplication.</p>\r\n<p>Level 2 closes the loop: <a href=\"#ch-17\">providers</a> as translators to every cloud API, <a href=\"#ch-18\">provisioners</a> as the last-resort escape hatch (with doctrine), <a href=\"#ch-19\">modules</a> as Lego bricks that package reuse. The <a href=\"#lab-1\">CAPSTONE</a> stitches every chapter together in one hands-on build: provider → VPC → 2 subnets → 4 instances → security group → output IPs → provisioner → destroy.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The Golden Path in 3 sentences</span>We start with the <b>pain</b> (ClickOps doesn't scale), learn the <b>blueprint</b> (HCL + state + plan), and end with the <b>proof</b> (a working cloud environment that comes up identically every time).</div>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 3 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 01</div><h1 id=\"what-is-infrastructure-as-code\">📐 What is Infrastructure as Code?</h1></div><span class=\"hmeta\">🟢 6 MIN · T1</span></div></div>\r\n<p>Manual server setup is the chef who \"just knows\" the dish — until they quit, and nobody can remake it. <b>Infrastructure as Code (IaC)</b> replaces tribal knowledge with a written recipe anyone can follow, with the same taste every time. <code>main.tf</code> is the blueprint; <code>terraform apply</code> is the construction crew.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The rule</span><b>Idempotence.</b> Apply the same code ten times → same infrastructure every time. <code>f(f(x)) = f(x)</code>. The property that makes IaC safe to retry, safe in CI, safe to share across teams.</div>\r\n<h3 id=\"the-5-step-loop-memorize\"><span class=\"n\">▣</span>The 5-step loop (memorize)</h3>\r\n<div class=\"frow\"><div class=\"blk b-amber\">1 · Write<small>.tf in Git</small></div><span class=\"harr\">→</span><div class=\"blk b-paper\">2 · Review<small>PR + fmt</small></div><span class=\"harr\">→</span><div class=\"blk b-teal\">3 · Plan<small>+/−/∼ diff</small></div><span class=\"harr\">→</span><div class=\"blk b-plum\">4 · Apply<small>API calls</small></div><span class=\"harr\">→</span><div class=\"blk b-green\">5 · Monitor<small>drift alarm</small></div></div>\r\n<p>Code says where to go · state remembers where you've been · refresh checks where you are.</p>\r\n<h3 id=\"why-it-exists-a-real-story\"><span class=\"n\">▣</span>Why it exists — a real story</h3>\r\n<p>Startup: 3 devs, 1 EC2 made by clicking. Works. Team grows to 20, need dev/staging/prod + 50 servers. Without IaC: nobody remembers the security-group rules, dev works / prod fails, the engineer who built it left, audit can't trace port openings, region outage = 3 weeks of clicking. With IaC: same company rebuilds prod in 12 minutes via <code>terraform apply -var-file=prod.tfvars</code>, rolls back via <code>git revert</code>, proves every change with a PR.</p>\r\n<div class=\"grid2\"><div class=\"panel\"><div class=\"ptitle\">❌ Manual (ClickOps)</div><ul><li>Snowflake, tribal knowledge</li><li>Slow, error-prone</li><li>No rollback, no audit</li><li>Rebuild = weeks</li></ul></div><div class=\"panel\"><div class=\"ptitle\">✅ Infrastructure as Code</div><ul><li>Every resource in code</li><li>Fast, parallel, automated</li><li><code>git revert</code> + apply</li><li>Rebuild = minutes</li></ul></div></div>\r\n<div class=\"mark m-fun\"><span class=\"tag\">😄 The recipe analogy</span>ClickOps = chef who \"just knows\" the dish. IaC = written recipe anyone can follow. Bonus: anyone can read the recipe and improve it. Bonus bonus: you can compare two recipes (PRs) to see what changed.</div>\r\n\r\n<p>⏭️ <b>Next:</b> Now that you know WHY, meet the contractor — <a href=\"#ch-02\">Chapter 2: What is Terraform + Why</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 4 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 02</div><h1 id=\"what-is-terraform-the-6-pillars-of-why\">💎 What is Terraform + The 6 Pillars of Why</h1></div><span class=\"hmeta\">🟢 7 MIN · T2 + T3</span></div></div>\r\n<p><b>Terraform</b> (HashiCorp, 2014, Go, MPL 2.0, open source) is a <b>multi-cloud standard</b> that builds, changes, and versions infrastructure safely. It manages existing providers (AWS, GCP, Azure, 3000+ more) and your own in-house solutions. Six reasons it wins, each with the objection already answered. 📝 2023+: new releases are BUSL — the MPL line continues as <b>OpenTofu</b>.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 Terraform in one sentence</span><b>Learn once, manage anything, with the best preview and biggest ecosystem.</b> 3000+ providers. The community has answered every error you'll hit.</div>\r\n<h3 id=\"the-6-pillars\"><span class=\"n\">▣</span>The 6 pillars</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">1 · IaC done right</div><p>Code replaces clicks; Git replaces memory.</p><div class=\"code mini\">git log --oneline -- infra/\r\ngit revert &lt;sha&gt; &amp;&amp; terraform apply</div><p><b>Objection</b> \"scripts do that\" → scripts aren't idempotent/previewable; Terraform is.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">2 · Platform-agnostic</div><div class=\"code mini\">resource \"aws_s3_bucket\" \"a\" { bucket = \"x\" }\r\nresource \"azurerm_resource_group\" \"b\" { name = \"rg\" }\r\nresource \"github_repository\" \"c\" { name = \"infra\" }</div><p>One <code>apply</code> touches 3 APIs. <b>Objection</b> \"we're AWS-only\" → still useful for GitHub/Cloudflare/Datadog in same run.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">3 · Plan before apply</div><div class=\"code mini\">Plan: 1 to add, 1 to change, 0 to destroy.\r\n  + aws_s3_bucket.new\r\n  ~ aws_instance.web (t3.micro → t3.small)</div><p>PR shows the diff as a comment. <code>plan -out=tfplan → apply tfplan</code> = reviewed == executed.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">4 · Coding best practices</div><div class=\"code mini\">terraform fmt -check &amp;&amp; terraform validate &amp;&amp; tflint &amp;&amp; checkov -d .</div><p>Remote state+lock, no secrets, small modules, tag all — same bar as app code.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">5 · Massive community</div><p>3000+ providers, 10k+ modules. Every error already answered. Hiring: most platform/DevOps posts name Terraform.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">6 · Speed + reliable</div><p>Graph-parallel builds. Idempotent re-applies. Enterprise: remote runs, locking, policy gates.</p></div>\r\n</div>\r\n<div class=\"mark m-fun\"><span class=\"tag\">😄 TF vs CFN — one-line</span><b>Unlocked phone + any carrier</b> (more setup, works everywhere) vs <b>carrier-locked</b> (free, deep integration, only one network). Pick unlocked when you travel clouds.</div>\r\n\r\n<p>⏭️ <b>Next:</b> Look under the hood — <a href=\"#ch-03\">Chapter 3: How Terraform Works (Core vs Plugins)</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 5 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 03</div><h1 id=\"how-terraform-works-core-vs-plugins\">🧠 How Terraform Works — Core vs Plugins</h1></div><span class=\"hmeta\">🟡 7 MIN · T4 + T9</span></div></div>\r\n<p>One-line: <b>Core reads your code and builds a graph; plugins do the dirty work talking to AWS/Azure/etc.</b> Core is the brain, providers are the hands. They communicate over gRPC (local RPC) — you almost never see the boundary, but knowing which side is the culprit saves hours.</p>\r\n<div class=\"rowc\"><div class=\"blk b-amber\">.tf code<small>WHAT</small></div><span class=\"harr\">→</span><div class=\"blk b-plum\">CORE<small>plan + graph</small></div><span class=\"harr\">→</span><div class=\"blk b-teal\">PROVIDER<small>HOW</small></div><span class=\"harr\">→</span><div class=\"blk b-ink\">AWS API<small>REAL</small></div></div>\r\n<p>State sits beside the core — its memory. <code>TF_LOG=DEBUG</code> reveals the gRPC chatter.</p>\r\n<h3 id=\"what-core-does-brain\"><span class=\"n\">▣</span>What core does (brain)</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Core job</th><th>Example</th></tr>\r\n<tr><td>Parse HCL + variables + tfvars</td><td><code>var.env</code> → <code>\"prod\"</code></td></tr>\r\n<tr><td>Build dependency graph</td><td><code>subnet → vpc</code> (auto from references)</td></tr>\r\n<tr><td>Order + parallelize</td><td>VPC first, then 3 subnets concurrently</td></tr>\r\n<tr><td>Diff (plan)</td><td>code says v2, state says v1 → <code>~ update</code></td></tr>\r\n<tr><td>Manage state + lock</td><td>S3 + DynamoDB, one writer</td></tr>\r\n<tr><td>Call plugins, never APIs</td><td>core never holds AWS keys — provider does</td></tr>\r\n</table></div>\r\n<h3 id=\"resource-vs-data-source-the-critical-distinction\"><span class=\"n\">▣</span>Resource vs data source (the critical distinction)</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">Resource — managed</div><div class=\"code mini\">resource \"aws_instance\" \"web\" {\r\n  ami = \"ami-123\"\r\n  tags = { Name = \"web\" }\r\n}</div><p>Terraform manages full lifecycle: create, update, delete. Counts in <code>plan</code>.</p></div>\r\n<div class=\"panel\"><div class=\"ptitle\">Data source — read-only</div><div class=\"code mini\">data \"aws_ami\" \"ubuntu\" {\r\n  most_recent = true\r\n  owners      = [\"099720109477\"]\r\n  filter { name = \"name\" values = [\"ubuntu/images/hvm-ssd/ubuntu-*-22.04*\"] }\r\n}</div><p>Lookup only — Terraform doesn't create or delete. Use for AMIs, AZs, secrets. Always fresh on every <code>plan</code>.</p></div>\r\n</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ The \"hidden dep\" trap</span>References handle 95% of ordering. For invisible deps (IAM eventual consistency, external side effects), use <code>depends_on = [...]</code> explicitly. <code>terraform graph | dot -Tpng &gt; g.png</code> to visualize the order.</div>\r\n\r\n<p>⏭️ <b>Next:</b> The brain is built. Give it hands — <a href=\"#ch-04\">Chapter 4: AWS Provider</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 6 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 04</div><h1 id=\"aws-provider-three-auth-patterns\">🔑 AWS Provider — Three Auth Patterns</h1></div><span class=\"hmeta\">🟡 7 MIN · T5</span></div></div>\r\n<p>The <code>provider \"aws\"</code> block plus <b>credentials that never touch code</b> = Terraform talking to your account. The provider checks sources in order — first hit wins. Get auth right once, every guide after this just works.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The #1 rule</span><b>No keys in code. Ever.</b> State files + git history keep secrets forever. Static keys in the provider block is the #1 way that gets repos breached.</div>\r\n<h3 id=\"auth-priority-order-first-hit-wins\"><span class=\"n\">▣</span>Auth priority order (first hit wins)</h3>\r\n<div class=\"frow\">\r\n<div class=\"blk b-amber\">1 · provider block<small>❌ leaks</small></div>\r\n<span class=\"harr\">→</span>\r\n<div class=\"blk b-teal\">2 · env vars<small>✓ CI/local</small></div>\r\n<span class=\"harr\">→</span>\r\n<div class=\"blk b-green\">3 · ~/.aws + profile<small>✓ humans</small></div>\r\n<span class=\"harr\">→</span>\r\n<div class=\"blk b-plum\">4 · SSO / role / OIDC<small>✓ teams</small></div>\r\n</div>\r\n<h3 id=\"three-patterns-you-ll-use\"><span class=\"n\">▣</span>Three patterns you'll use</h3>\r\n<div class=\"panel\">\r\n<div class=\"ptitle\">Pattern A · env vars (CI, scripts)</div>\r\n<div class=\"code mini\">export AWS_ACCESS_KEY_ID=\"AKIA...\"\r\nexport AWS_SECRET_ACCESS_KEY=\"...\"\r\nexport AWS_REGION=\"us-east-1\"\r\nterraform plan</div>\r\n</div>\r\n<div class=\"panel\">\r\n<div class=\"ptitle\">Pattern B · named profile (humans daily-driving)</div>\r\n<div class=\"code mini\">$ aws configure --profile study\r\n$ export AWS_PROFILE=study\r\n$ terraform plan</div>\r\n</div>\r\n<div class=\"panel\">\r\n<div class=\"ptitle\">Pattern C · OIDC in CI (no stored secrets)</div>\r\n<div class=\"code mini\">permissions: { id-token: write }\r\n- uses: aws-actions/configure-aws-credentials@v4\r\n  with: { role-to-assume: arn:..., aws-region: us-east-1 }</div>\r\n</div>\r\n<h3 id=\"safety-belt\"><span class=\"n\">▣</span>Safety belt</h3>\r\n<div class=\"code\">provider \"aws\" {\r\n  region = \"us-east-1\"\r\n  allowed_account_ids = [\"123456789012\"]\r\n  default_tags { tags = { Env = \"study\", ManagedBy = \"terraform\" } }\r\n}</div>\r\n<p>If creds accidentally point at prod, <code>terraform plan</code> fails fast. The 2-minute seatbelt that prevents the 2-day outage.</p>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Error you'll hit</span><code>No valid credential sources found</code> → nothing exported, no profile. Run <code>aws sts get-caller-identity</code> first; set <code>AWS_PROFILE</code> or env vars.</div>\r\n\r\n<p>⏭️ <b>Next:</b> Provider is wired. Draw your first real resource — <a href=\"#ch-05\">Chapter 5: Your First Resource (aws_vpc)</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 7 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 05</div><h1 id=\"your-first-resource-aws-vpc\">🧱 Your First Resource — aws_vpc</h1></div><span class=\"hmeta\">🟢 8 MIN · T6</span></div></div>\r\n<p>A VPC is the <b>plot of land</b> — a logically isolated virtual network where every other AWS resource lives. One per environment. Subnets divide it into AZs, route tables decide who talks to whom, gateways open the doors. Every EC2/RDS/ALB <b>must</b> launch in a VPC.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 VPC = network boundary</span>Pick a CIDR in private RFC1918 space. <code>10.0.0.0/16</code> = 65,536 IPs. AWS reserves 5 per subnet, so plan <code>/16</code> for VPC, <code>/24</code> per subnet. Default VPC exists — <b>never use it for new work.</b></div>\r\n<h3 id=\"resource-block-anatomy-memorize\"><span class=\"n\">▣</span>Resource block anatomy (memorize)</h3>\r\n<div class=\"code\">resource \"aws_vpc\" \"main\" {       <span class=\"c\">//  ┌── type (RESOURCE_TYPE.LOCAL_NAME)</span>\r\n  cidr_block = \"10.0.0.0/16\"       <span class=\"c\">//  │  argument: what you want</span>\r\n  enable_dns_hostnames = true      <span class=\"c\">//  │</span>\r\n  enable_dns_support   = true      <span class=\"c\">//  │</span>\r\n  instance_tenancy = \"default\"    <span class=\"c\">//  │  \"dedicated\" = single-tenant $$</span>\r\n  tags = { Name = \"study-vpc\", Env = \"dev\" }\r\n}</div>\r\n<p>Every resource = <code>resource \"TYPE\" \"LOCAL_NAME\" { args }</code>. Local name is Terraform-only — AWS knows the resource by ID. Reference as <code>aws_vpc.main.id</code>, <code>aws_vpc.main.cidr_block</code>, etc.</p>\r\n<h3 id=\"the-pro-pattern-registry-module-beats-hand-rolled\"><span class=\"n\">▣</span>The pro pattern — registry module beats hand-rolled</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">❌ Hand-rolled (200 lines)</div><p>You write every subnet, every route table, every association. Good for learning; bad for prod.</p>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\">✅ Registry module (10 lines)</div>\r\n<div class=\"code mini\">module \"vpc\" {\r\n  source  = \"terraform-aws-modules/vpc/aws\"\r\n  version = \"~&gt; 5.1\"   <span class=\"g\"># pin!</span>\r\n\r\n  name = \"study\"\r\n  cidr = \"10.0.0.0/16\"\r\n  azs  = [\"us-east-1a\", \"us-east-1b\", \"us-east-1c\"]\r\n\r\n  public_subnets   = [\"10.0.1.0/24\", \"10.0.2.0/24\", \"10.0.3.0/24\"]\r\n  private_subnets  = [\"10.0.11.0/24\", \"10.0.12.0/24\", \"10.0.13.0/24\"]\r\n  database_subnets = [\"10.0.21.0/24\", \"10.0.22.0/24\", \"10.0.23.0/24\"]\r\n\r\n  enable_nat_gateway = true\r\n  single_nat_gateway = true   <span class=\"g\"># dev only</span>\r\n\r\n  tags = { Env = \"dev\" }\r\n}</div>\r\n</div>\r\n</div>\r\n<p>Rule: use the module in any real project. Hand-roll only when learning or you need a non-standard layout.</p>\r\n\r\n<p>⏭️ <b>Next:</b> The plot is drawn. Divide it into AZs and open the gates — <a href=\"#ch-06\">Chapter 6: VPC Networking</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 8 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 06</div><h1 id=\"subnets-route-tables-igw-nat\">🌐 Subnets · Route Tables · IGW · NAT</h1></div><span class=\"hmeta\">🟡 8 MIN · T6 (deep)</span></div></div>\r\n<p>VPC is the plot. <b>Subnets</b> divide it into AZs. <b>Route tables</b> decide who can talk to whom. <b>Internet Gateway</b> opens the public door. <b>NAT Gateway</b> lets private subnets sneak out for updates without being reachable from the internet.</p>\r\n<div class=\"rowc\"><div class=\"blk b-ink\">VPC<small>10.0.0.0/16</small></div></div>\r\n<div class=\"fstem\"></div>\r\n<div class=\"rowc\"><div class=\"blk b-amber\">IGW<small>1 per VPC</small></div></div>\r\n<div class=\"fstem\"></div>\r\n<div class=\"rowc\"><div class=\"blk b-amber\">pub 1a</div><div class=\"blk b-amber\">pub 1b</div><div class=\"blk b-amber\">pub 1c</div></div>\r\n<p>Public subnets share a route table pointing 0.0.0.0/0 → IGW. Private subnets share one pointing 0.0.0.0/0 → NAT (in a public subnet). DB subnets have <b>no default route</b> — never.</p>\r\n<h3 id=\"the-4-resources-you-touch-every-day\"><span class=\"n\">▣</span>The 4 resources you touch every day</h3>\r\n<div class=\"code\">resource \"aws_subnet\" \"public\" {\r\n  count                   = length(local.azs)\r\n  vpc_id                  = aws_vpc.main.id\r\n  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)\r\n  availability_zone       = local.azs[count.index]\r\n  map_public_ip_on_launch = true\r\n  tags = { Name = \"public-${local.azs[count.index]}\", Tier = \"public\" }\r\n}</div>\r\n<div class=\"code\">resource \"aws_internet_gateway\" \"igw\" { vpc_id = aws_vpc.main.id }\r\nresource \"aws_eip\" \"nat\" { domain = \"vpc\" }\r\nresource \"aws_nat_gateway\" \"nat\" {\r\n  allocation_id = aws_eip.nat.id\r\n  subnet_id     = aws_subnet.public[0].id\r\n  depends_on    = [aws_internet_gateway.igw]\r\n}</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Gotcha</span>AWS reserves <b>5 IPs per subnet</b>. A <code>/24</code> = 251 usable. <b>Never hardcode AZs</b> — use <code>data \"aws_availability_zones\"</code> + <code>slice(..., 0, 3)</code>. A subnet is \"public\" only when its route table points 0.0.0.0/0 → IGW.</div>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">Day-2 ops</div>\r\n<ul><li>✅ Flow logs on the VPC</li><li>✅ 1 NAT/AZ in prod, 1 in dev</li><li>✅ Tag every subnet: Tier + AZ</li><li>✅ DB route table: <b>no default route, ever</b></li><li>✅ Gateway endpoints for S3 + DynamoDB</li></ul></div>\r\n<div class=\"panel\"><div class=\"ptitle\">Errors you'll hit</div>\r\n<ul><li><code>CIDR overlaps with existing</code> → use <code>cidrsubnet</code></li><li><code>host bits set in CIDR</code> → <code>10.0.1.0/24</code> not <code>10.0.1.5/24</code></li><li><code>NAT in private subnet</code> → put in public</li><li><code>cannot delete subnet: dependencies</code> → destroy in reverse</li></ul></div>\r\n</div>\r\n\r\n<p>⏭️ <b>Next:</b> Network is built. Now wire the engine — <a href=\"#ch-07\">Chapter 7: terraform init</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 9 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 07</div><h1 id=\"terraform-init-what-it-really-does\">🔌 terraform init — What It Really Does</h1></div><span class=\"hmeta\">🟡 6 MIN · T7</span></div></div>\r\n<p><code>terraform init</code> is the first command of any project — and the one people forget has <b>two jobs</b>, not one. It installs provider binaries AND wires up the backend (if you have one). No cloud calls; think <code>npm install</code> for infra.</p>\r\n<div class=\"mark m-tip\"><span class=\"tag\">💡 Safe to re-run</span>Init never touches real infra. Re-run it anytime you change <code>required_providers</code>, swap the backend block, or upgrade a provider. <code>-upgrade</code> bumps to newest allowed by <code>~&gt;</code>. <code>-reconfigure</code> forgets the saved backend choice.</div>\r\n<h3 id=\"job-1-always-install-providers-modules\"><span class=\"n\">▣</span>Job 1 (always) — install providers + modules</h3>\r\n<div class=\"code\">$ terraform init\r\nInitializing the backend...\r\nInitializing provider plugins...\r\n- Installing hashicorp/aws v5.0.1\r\n- Installed hashicorp/aws v5.0.1 (signed by HashiCorp)\r\n- Installing hashicorp/local v2.5.1\r\n- Installed hashicorp/local v2.5.1 (signed by HashiCorp)\r\n\r\nTerraform has been successfully initialized!</div>\r\n<p>What lands on disk: <code>.terraform/providers/.../terraform-provider-aws_v5.0.1</code> (the binary) + <code>.terraform.lock.hcl</code> (exact version + hashes, commit this).</p>\r\n<h3 id=\"job-2-only-with-a-backend-block-wire-up-state-storage\"><span class=\"n\">▣</span>Job 2 (only with a backend block) — wire up state storage</h3>\r\n<div class=\"code\">$ terraform init -migrate-state\r\nInitializing the backend...\r\nBackend type: s3\r\nDo you want to copy existing state to the new backend? yes\r\nSuccessfully configured the backend \"s3\"!\r\n\r\nTerraform has been successfully initialized!</div>\r\n<p>Init performs <code>HeadBucket</code> and <code>DescribeTable</code> during setup. <b>Missing bucket?</b> <code>NoSuchBucket</code> error. <b>Backend resources must exist BEFORE first init</b> — bootstrap folder with local state creates them.</p>\r\n<h3 id=\"the-gitignore-canon\"><span class=\"n\">▣</span>The .gitignore canon</h3>\r\n<div class=\"code\">.terraform/           <span class=\"g\"># downloaded provider binaries — always ignore</span>\r\n*.tfstate             <span class=\"g\"># state file — has secrets, NEVER commit</span>\r\n*.tfstate.backup      <span class=\"g\"># backup created by apply</span>\r\n*.tfvars              <span class=\"g\"># real values — ignore</span>\r\n!example.tfvars       <span class=\"g\"># except the example template</span>\r\ntfplan                <span class=\"g\"># plan output binary</span>\r\n.terraform.lock.hcl   <span class=\"g\"># COMMIT THIS — pins versions + hashes</span></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ The lock file IS in git</span>Counter-intuitive but critical: the lock file makes your team byte-identical. <code>terraform providers lock</code> regenerates hashes for all platforms. CI and laptop get the same provider binary.</div>\r\n\r\n<p>⏭️ <b>Next:</b> The engine is wired. The 7-command loop — <a href=\"#ch-08\">Chapter 8: plan · apply · tfstate</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 10 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 08</div><h1 id=\"plan-apply-tfstate-the-core-loop\">🔁 plan · apply · tfstate — The Core Loop</h1></div><span class=\"hmeta\">🟡 7 MIN · T8 + T10 + T15</span></div></div>\r\n<p>Every Terraform session runs the same 7-command loop. <code>init</code> is the install (no cloud calls), <code>plan</code> is the dress rehearsal, <code>apply</code> is the real show, and a second <code>apply</code> proves idempotence by saying \"No changes.\" State is the ledger written by <code>apply</code> and read by every subsequent <code>plan</code>.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The contract</span><b>plan</b> is a contract, not a forecast. <code>plan -out=tfplan</code> + <code>apply tfplan</code> guarantees: what you reviewed = what was executed. <b>Never edit state by hand</b> — use <code>terraform state mv/rm</code> instead.</div>\r\n<h3 id=\"the-7-command-loop-every-session\"><span class=\"n\">▣</span>The 7-command loop (every session)</h3>\r\n<div class=\"code\">terraform version    <span class=\"g\"># 0. what toolchain?</span>\r\nterraform init       <span class=\"g\"># 1. install providers + modules → .terraform/ + .lock.hcl</span>\r\nterraform fmt        <span class=\"g\"># 2. canonical formatting (CI gate: fmt -check)</span>\r\nterraform validate   <span class=\"g\"># 3. syntax check (offline, no cloud)</span>\r\nterraform plan       <span class=\"g\"># 4. preview diff (+/~/−) — read this carefully</span>\r\nterraform apply      <span class=\"g\"># 5. execute + write state</span>\r\nterraform apply      <span class=\"g\"># 6. prove idempotence → \"No changes\"</span></div>\r\n<p>Apply twice in a row: second one says No changes. That's idempotence made visible.</p>\r\n<h3 id=\"what-tfstate-actually-contains\"><span class=\"n\">▣</span>What tfstate actually contains</h3>\r\n<div class=\"tree\">{\r\n  \"version\": 4,\r\n  \"terraform_version\": \"1.10.0\",\r\n  \"serial\": 12,\r\n  \"outputs\": { \"vpc_id\": { \"value\": \"vpc-0ab123\", \"type\": \"string\" } },\r\n  \"resources\": [\r\n    {\r\n      \"mode\": \"managed\",\r\n      \"type\": \"aws_vpc\",\r\n      \"name\": \"main\",\r\n      \"provider\": \"provider[\"registry.terraform.io/hashicorp/aws\"]\",\r\n      \"instances\": [{\r\n        \"schema_version\": 1,\r\n        \"attributes\": {\r\n          \"id\": \"vpc-0ab123\",\r\n          \"cidr_block\": \"10.0.0.0/16\",\r\n          \"enable_dns_hostnames\": true,\r\n          \"tags\": { \"Env\": \"dev\", \"Name\": \"study-vpc\" }\r\n        }\r\n      }]\r\n    }\r\n  ]\r\n}</div>\r\n<p>State stores: resource IDs, all attributes, dependencies, provider metadata. The mapping from your code addresses (e.g. <code>aws_vpc.main</code>) to real cloud IDs (e.g. <code>vpc-0ab123</code>).</p>\r\n\r\n<p>⏭️ <b>Next:</b> You have the loop. Now meet the three things it compares — <a href=\"#ch-09\">Chapter 9: The 3-State Model</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 11 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 09</div><h1 id=\"the-3-state-model-code-state-reality\">📒 The 3-State Model — code · state · reality</h1></div><span class=\"hmeta\">🟡 7 MIN · T11</span></div></div>\r\n<p>Every plan is a 3-way comparison. Learn these three names — interviews ask them directly. <b>Desired state</b> is your <code>.tf</code> files. <b>Known state</b> is <code>terraform.tfstate</code>. <b>Real state</b> is what AWS looks like right now (after refresh).</p>\r\n<div class=\"rowc\"><div class=\"blk b-amber\">1 · DESIRED<small>code</small></div><div class=\"stem\"></div><div class=\"blk b-plum\">2 · KNOWN<small>tfstate</small></div><div class=\"stem\"></div><div class=\"blk b-teal\">3 · REAL<small>AWS API</small></div></div>\r\n<p>Refresh = read REAL via API, compare to KNOWN. Diff = compare DESIRED to KNOWN. Anything off → plan shows +/~/−. State does 4 jobs: <b>track</b> (what's managed), <b>compare</b> (desired vs known), <b>metadata</b> (IDs/IPs/ARNs), <b>perform</b> (cache so plan stays fast).</p>\r\n<h3 id=\"reading-a-plan-output\"><span class=\"n\">▣</span>Reading a plan output</h3>\r\n<div class=\"code\">Terraform will perform the following actions:\r\n\r\n  <span class=\"s\">+ aws_instance.web</span>              <span class=\"c\"># create</span>\r\n  <span class=\"y\">~ aws_s3_bucket.notes</span>           <span class=\"c\"># update in-place</span>\r\n  <span class=\"m\">-/+ aws_instance.replace</span>         <span class=\"c\"># destroy then create (force-new)</span>\r\n  <span class=\"r\">- aws_security_group.old</span>        <span class=\"c\"># destroy</span>\r\n\r\nPlan: 1 to add, 1 to change, 1 to destroy.</div>\r\n<div class=\"table-scroll\"><table><tr><th>Symbol</th><th>Means</th><th>Danger</th></tr>\r\n<tr><td><code>+</code> create</td><td>in code, not in state</td><td><span class=\"ok\">safe</span></td></tr>\r\n<tr><td><code>~</code> update in-place</td><td>same ID, new attrs</td><td><span class=\"ok\">safe</span> (low)</td></tr>\r\n<tr><td><code>-/+</code> destroy+create</td><td>attribute forces new</td><td>⚠️ data loss</td></tr>\r\n<tr><td><code>-</code> destroy</td><td>in state, gone from code</td><td>🔴 read every line</td></tr>\r\n</table></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Rename trap</span>Terraform's identity is the <b>address</b> (<code>aws_instance.web</code>), not attributes. Rename the local name → destroy + create. <b>Use a <code>moved</code> block</b> for safe renames (preserves state, no rebuild).</div>\r\n\r\n<p>⏭️ <b>Next:</b> You have the model. Now store the ledger safely — <a href=\"#ch-10\">Chapter 10: State Risks &amp; Remote Backend</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 12 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 10</div><h1 id=\"state-risks-amp-remote-backend-s3-dynamodb\">☁️ State Risks &amp; Remote Backend (S3 + DynamoDB)</h1></div><span class=\"hmeta\">🟡 8 MIN · T12</span></div></div>\r\n<p>Local state dies with the laptop. The whole team needs <b>one</b> state, in a place that locks, versions, and survives. The cure: <b>S3 stores the JSON snapshots</b>; <b>DynamoDB holds the mutex</b>. Both, configured before the second human exists.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The 3 pains of local state</span>\r\n<b>①</b> Teammate applies from their laptop → your state is stale → resources duplicated. <b>②</b> Two <code>apply</code> at once → corrupt JSON or half-written resources. <b>③</b> Laptop dies / file deleted → management history gone. <b>All three cured by S3 + DynamoDB.</b></div>\r\n<h3 id=\"backend-anatomy\"><span class=\"n\">▣</span>Backend anatomy</h3>\r\n<div class=\"code\">terraform {\r\n  backend \"s3\" {\r\n    bucket         = \"my-study-tfstate-12345\"   <span class=\"g\"># unique</span>\r\n    key            = \"dev/terraform.tfstate\"    <span class=\"g\"># per-env path</span>\r\n    region         = \"us-east-1\"\r\n    dynamodb_table = \"tfstate-locks\"\r\n    encrypt        = true\r\n  }\r\n}</div>\r\n<p>S3 = JSON snapshots (versioned, encrypted). DynamoDB = mutex (conditional-write row). Two different stores, two different jobs.</p>\r\n<h3 id=\"bootstrap-chicken-and-egg\"><span class=\"n\">▣</span>Bootstrap (chicken-and-egg)</h3>\r\n<div class=\"code\">$ aws s3api create-bucket --bucket my-study-tfstate-12345\r\n$ aws s3api put-bucket-versioning --bucket my-study-tfstate-12345     --versioning-configuration Status=Enabled\r\n$ aws s3api put-bucket-encryption --bucket my-study-tfstate-12345     --server-side-encryption-configuration '{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"AES256\"}}]}'\r\n$ aws dynamodb create-table --table-name tfstate-locks     --attribute-definitions AttributeName=LockID,AttributeType=S     --key-schema AttributeName=LockID,KeyType=HASH --billing-mode PAY_PER_REQUEST</div>\r\n<p>Pro pattern: keep a tiny <code>bootstrap/</code> folder whose ONLY job is creating bucket + table with local state, then never touch it again.</p>\r\n<h3 id=\"how-locking-works-3-steps\"><span class=\"n\">▣</span>How locking works (3 steps)</h3>\r\n<div class=\"frow\"><div class=\"blk b-amber\">1 · apply starts<small>conditional-write LockID</small></div><span class=\"harr\">→</span><div class=\"blk b-crimson\">2 · second apply<small>Error: lock held</small></div><span class=\"harr\">→</span><div class=\"blk b-green\">3 · first apply ends<small>DELETE LockID</small></div></div>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">With lock (safe)</div><div class=\"code mini\">Shell A: terraform apply ............ (holds lock, writing)\r\nShell B: terraform apply → Error: Error acquiring the state lock\r\n  Lock Info: ID xxx, Who: teammate@laptop, Created: 10:02:11\r\nB waits or exits → no corruption.</div>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\">Without lock (disaster)</div><div class=\"code mini\">10:00:00  state v1: { web }\r\n10:00:20  YOU apply → v2: { web, db }\r\n10:00:25  SARA apply → OVERWRITES → { web, cache }\r\n10:00:26  db exists in AWS. Terraform forgot it.\r\n→ ghost resource. bill grows quietly.</div>\r\n</div>\r\n</div>\r\n\r\n<p>⏭️ <b>Next:</b> You have the backend. Now the lock lifecycle — <a href=\"#ch-11\">Chapter 11: State Locking</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 13 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 11</div><h1 id=\"state-locking-the-mutex-explained\">🔒 State Locking — The Mutex Explained</h1></div><span class=\"hmeta\">🟡 7 MIN · T13</span></div></div>\r\n<p>Two engineers + concurrent apply = corrupted state. The fix: a <b>DynamoDB lock table</b> holds a single row per backend key. First apply grabs it (conditional-write), others fail fast, lock releases when apply finishes. The contract: <b>only one writer to state at a time, ever.</b></p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The lock lifecycle</span><b>apply starts</b> → conditional-write LockID → if row exists, <b>fail fast</b> with who/when/operation → if acquired, <b>do work + write new state to S3</b> → on success, <b>delete the lock row</b>. The lock is a row, not a file.</div>\r\n<h3 id=\"what-the-lock-error-looks-like\"><span class=\"n\">▣</span>What the lock error looks like</h3>\r\n<div class=\"code\">$ terraform apply\r\n<span class=\"r\">│ Error: Error acquiring the state lock</span>\r\n<span class=\"g\">│</span>\r\n<span class=\"g\">│ Error acquiring the state lock: ConditionalCheckFailedException:</span>\r\n<span class=\"g\">│   Conditional Write failed: LockID = my-bucket/dev/terraform.tfstate</span>\r\n<span class=\"g\">│</span>\r\n<span class=\"g\">│ Lock Info:</span>\r\n<span class=\"g\">│   ID:        abc-123-def-456</span>\r\n<span class=\"g\">│   Path:      my-bucket/dev/terraform.tfstate</span>\r\n<span class=\"g\">│   Operation: OperationTypeApply</span>\r\n<span class=\"g\">│   Who:       teammate@laptop</span>\r\n<span class=\"g\">│   Created:   2026-09-07 10:02:11 UTC</span>\r\n<span class=\"g\">│   Version:   1.5.0</span>\r\n<span class=\"g\">│</span>\r\n<span class=\"g\">│ Terraform acquires a state lock to protect the state from being</span>\r\n<span class=\"g\">│ written by multiple users at the same time. Please resolve the issue</span>\r\n<span class=\"g\">│ by removing the lock manually.</span></div>\r\n<h3 id=\"force-unlock-the-danger-zone\"><span class=\"n\">▣</span>Force-unlock — the danger zone</h3>\r\n<div class=\"code\"># Step 1: read the error — Who, Operation, Created\r\n# Step 2: CONFIRM the holder is dead\r\n#   $ ps aux | grep terraform       <span class=\"g\"># on their machine</span>\r\n#   ask in chat / check CI run status\r\n# Step 3: only then, release it\r\n$ terraform force-unlock abc-123-def-456\r\nDo you really want to force-unlock?  <span class=\"g\"># interactive confirm</span>\r\n<span class=\"g\"># CI flag (no prompt, dangerous):</span>\r\n$ terraform force-unlock -force abc-123-def-456\r\n\r\n# Step 4: PROVE HEALTH before continuing\r\n$ terraform plan   <span class=\"g\"># expect sane diff, NOT \"create the world\"</span></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Never hand-delete the lock row</span>Tempting: open DynamoDB console, delete the row, done in 10 seconds. <b>Don't.</b> The command exists because the console bypasses all the safety checks (wrong table? wrong key? live lock?). The error message already told you exactly which row to target.</div>\r\n\r\n<p>⏭️ <b>Next:</b> You have the lock. Now the state surgery tools — <a href=\"#ch-12\">Chapter 12: State Subcommands</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 14 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 12</div><h1 id=\"state-subcommands-cli-extras\">🔧 State Subcommands + CLI Extras</h1></div><span class=\"hmeta\">🟡 7 MIN · T14 + T16</span></div></div>\r\n<p>The state is a JSON file. The <code>terraform state</code> subcommands let you <b>operate on it without recreating resources</b>. Refactor names, drop orphans, adopt existing infra. Other CLIs (<code>fmt</code>, <code>graph</code>) keep the code clean and the dependencies visible.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The 5 state subcommands</span>State subcommands change <b>state, not infrastructure</b>. <code>state rm</code> stops managing without deleting. <code>state mv</code> renames without recreating. <code>import</code> adopts existing infra into management.</div>\r\n<h3 id=\"state-subcommands-5-essential\"><span class=\"n\">▣</span>State subcommands (5 essential)</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Command</th><th>What it does</th><th>When to use</th></tr>\r\n<tr><td><code>state list</code></td><td>List every resource address in state</td><td>\"What's actually managed here?\"</td></tr>\r\n<tr><td><code>state show &lt;addr&gt;</code></td><td>Show the full attributes of one resource</td><td>\"What's the actual ID of this VPC?\"</td></tr>\r\n<tr><td><code>state pull</code></td><td>Download the raw state JSON to stdout</td><td>Backup, debugging, hand inspection</td></tr>\r\n<tr><td><code>state mv &lt;from&gt; &lt;to&gt;</code></td><td>Rename in state (no recreate)</td><td>Refactor <code>web</code> → <code>app</code> without rebuilding</td></tr>\r\n<tr><td><code>state rm &lt;addr&gt;</code></td><td>Stop managing (does NOT delete from AWS)</td><td>Adopt a manual resource, drop an orphan</td></tr>\r\n<tr><td><code>terraform import &lt;addr&gt; &lt;id&gt;</code></td><td>Adopt existing infra into state</td><td>\"Terraform forgot this VPC, here's the ID\"</td></tr>\r\n</table></div>\r\n<p><code>import</code> adopts but does NOT write config for you. Write the matching <code>resource</code> block → <code>import</code> → <code>plan</code> till clean, or the next <code>plan</code> will try to recreate it.</p>\r\n<h3 id=\"the-other-clis-you-ll-use\"><span class=\"n\">▣</span>The other CLIs you'll use</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\"><code>fmt</code> — canonical formatting</div>\r\n<div class=\"code mini\">$ terraform fmt -check   <span class=\"g\"># CI gate: exit 1 if not formatted</span>\r\n$ terraform fmt           <span class=\"g\"># fix in place</span></div>\r\n<p>Run before every commit. No-op if already formatted. Add to pre-commit hook.</p>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\"><code>graph</code> — dependency map</div>\r\n<div class=\"code mini\">$ terraform graph | dot -Tsvg &gt; graph.svg\r\n<span class=\"g\"># installs graphviz, generates SVG of dep graph</span></div>\r\n<p>Visualize the actual order Terraform will create things in. Great for debugging hidden deps.</p>\r\n</div>\r\n</div>\r\n<div class=\"mark m-fun\"><span class=\"tag\">😄 The rename trap, again</span>Renaming <code>aws_instance.web</code> → <code>aws_instance.app</code> in your <code>.tf</code> is a <b>destroy + create</b>. <b>Always use <code>state mv</code> first</b>, then rename in code. Or use a <code>moved</code> block (stateful rename, no recreate).</div>\r\n\r\n<p>⏭️ <b>Next:</b> Day 1 closes. Day 2 opens: <a href=\"#ch-14\">Variables &amp; the precedence ladder</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 15 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 13</div><h1 id=\"fmt-amp-destroy-canon-format-safe-teardown\">🧹 fmt &amp; destroy — Canon Format, Safe Teardown</h1></div><span class=\"hmeta\">🟢 5 MIN · T15</span></div></div>\r\n<p><code>terraform fmt</code> is your formatting pre-commit hook. <code>terraform destroy</code> is your teardown command — same plan machinery as <code>apply</code>, opposite direction. Both are gateable, both are CI-runnable, both deserve respect.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 destroy is just apply in reverse</span>Same plan/apply loop, but every resource is destroyed instead of created. <code>terraform destroy</code> prompts for confirmation; <code>-auto-approve</code> skips it (use in CI, never in interactive dev).</div>\r\n<h3 id=\"fmt-before-after\"><span class=\"n\">▣</span>fmt before → after</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">Before</div>\r\n<div class=\"code mini\">resource  \"aws_vpc\"   \"main\"{\r\ncidr_block=\"10.0.0.0/16\"\r\n   tags   =   {Name=\"x\",Env=\"dev\"}\r\n}</div>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\">After <code>fmt</code></div>\r\n<div class=\"code mini\">resource \"aws_vpc\" \"main\" {\r\n  cidr_block = \"10.0.0.0/16\"\r\n\r\n  tags = {\r\n    Env  = \"dev\"\r\n    Name = \"x\"\r\n  }\r\n}</div>\r\n</div>\r\n</div>\r\n<p>Two-space indent, aligned <code>=</code>, sorted tag keys, blank line between blocks. <code>terraform fmt -check</code> fails CI if not formatted (exit 1). <code>terraform fmt</code> rewrites in place.</p>\r\n<h3 id=\"destroy-the-teardown-pattern\"><span class=\"n\">▣</span>destroy — the teardown pattern</h3>\r\n<div class=\"code\">$ terraform plan -destroy -out=kill.plan\r\n<span class=\"g\"># preview what's about to die (always plan first)</span>\r\n\r\n$ terraform apply kill.plan\r\n<span class=\"g\"># applies EXACTLY the destroy plan</span>\r\n\r\n$ terraform destroy\r\n<span class=\"g\"># interactive: prompts \"Do you really want to destroy?\"</span>\r\n\r\n$ terraform destroy -auto-approve\r\n<span class=\"g\"># CI: skips prompt — gate behind human approval</span></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Permanence</span>destroy is <b>not</b> reversible. State is updated, AWS resources are gone, bills stop. For anything holding data (RDS, S3 buckets), use <code>prevent_destroy = true</code> in the resource block to fail the destroy with a clear error.</div>\r\n<h3 id=\"destroy-in-the-lab-vs-prod\"><span class=\"n\">▣</span>destroy in the lab vs prod</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">Lab / dev env</div><ul><li>Always destroy at end of session</li><li>Saves $$, prevents zombie resources</li><li>Use <code>-auto-approve</code> in CI</li></ul></div>\r\n<div class=\"panel\"><div class=\"ptitle\">Prod</div><ul><li>Almost never run naked <code>destroy</code></li><li>Use <code>prevent_destroy = true</code> on critical resources</li><li>Use <code>-target</code> to scope down to specific resources</li></ul></div>\r\n</div>\r\n\r\n<p>⏭️ <b>Next:</b> Day 1 done. <a href=\"#ch-14\">Day 2: Variables</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 16 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 14</div><h1 id=\"variables-amp-the-precedence-ladder\">🎚️ Variables &amp; the Precedence Ladder</h1></div><span class=\"hmeta\">🟡 8 MIN · T17 + T18</span></div></div>\r\n<p>Same code, many environments. <b>Variables</b> parameterize inputs. The <b>precedence ladder</b> determines which value wins when multiple are provided. Memorize it: the <b>lowest priority wins</b>.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The precedence ladder</span><b>defaults &lt; <code>terraform.tfvars</code> (auto-loaded) &lt; <code>-var</code> flag (CLI) &lt; <code>TF_VAR_*</code> env vars (CI/CD + secrets)</b>. Use <code>.tfvars</code> per env, override at runtime, never edit code.</div>\r\n<h3 id=\"variables-the-full-anatomy\"><span class=\"n\">▣</span>Variables — the full anatomy</h3>\r\n<div class=\"code\"># variables.tf\r\nvariable \"env\" {\r\n  type        = string\r\n  default     = \"dev\"\r\n  description = \"which environment we're targeting\"\r\n\r\n  validation {\r\n    condition     = contains([\"dev\", \"staging\", \"prod\"], var.env)\r\n    error_message = \"env must be dev/staging/prod.\"\r\n  }\r\n}\r\n\r\nvariable \"instance_type\" {\r\n  type    = string\r\n  default = \"t3.micro\"\r\n}\r\n\r\n# main.tf — reference as var.NAME\r\nresource \"aws_instance\" \"web\" {\r\n  ami           = data.aws_ami.ubuntu.id\r\n  instance_type = var.instance_type\r\n  tags          = { Env = var.env }\r\n}</div>\r\n<h3 id=\"the-4-ways-to-pass-variables\"><span class=\"n\">▣</span>The 4 ways to pass variables</h3>\r\n<div class=\"code\"># 1. defaults in variables.tf (lowest priority)\r\n# 2. terraform.tfvars (auto-loaded if present)\r\nenv             = \"dev\"\r\ninstance_type   = \"t3.micro\"\r\n\r\n# 3. -var flag (one-off, highest)\r\n$ terraform plan -var=\"env=prod\" -var=\"instance_type=t3.small\"\r\n\r\n# 4. TF_VAR_* env vars (CI/CD + secrets — never in code!)\r\n$ export TF_VAR_env=staging\r\n$ export TF_VAR_db_password=$(cat ~/.dbpass)</div>\r\n<p><b>Secrets rule:</b> never in <code>.tf</code> or <code>.tfvars</code> (both end up in PRs). Use <code>TF_VAR_*</code> env vars from your CI secret store (GitHub Actions secrets, Vault, etc.).</p>\r\n<div class=\"mark m-fun\"><span class=\"tag\">😄 The \"which one wins\" gotcha</span>You have <code>default = \"dev\"</code> in variables.tf AND <code>-var=\"env=prod\"</code> on the CLI. <b>Prod wins</b> (higher priority, overrides default). Run <code>terraform console</code> and type <code>var.env</code> to see what's actually in scope right now.</div>\r\n\r\n<p>⏭️ <b>Next:</b> One config, many environments — <a href=\"#ch-15\">Workspaces &amp; Advanced HCL</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 17 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 15</div><h1 id=\"workspaces-amp-advanced-hcl-count-for-each\">🗂️ Workspaces &amp; Advanced HCL (count · for_each)</h1></div><span class=\"hmeta\">🟡 8 MIN · T19 + T20</span></div></div>\r\n<p>One config, isolated state per env (<b>workspaces</b>). One block, N copies (<b>count</b>). One block, N named copies (<b>for_each</b>). These three patterns are how you stop duplicating config.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The right tool for N copies</span><b>for_each</b> wins almost every time. Removing one named key doesn't churn the rest (stable keys). <code>count</code> with index removal renumbers, breaking all addresses.</div>\r\n<h3 id=\"workspaces-same-code-isolated-state\"><span class=\"n\">▣</span>Workspaces — same code, isolated state</h3>\r\n<div class=\"code\">$ terraform workspace list\r\n<span class=\"g\">* default</span>\r\n\r\n$ terraform workspace new dev\r\nCreated and switched to workspace \"dev\"!\r\n\r\n$ terraform workspace new prod\r\n$ terraform workspace select dev    <span class=\"g\"># switch back</span>\r\n$ terraform workspace show          <span class=\"g\"># current: dev</span></div>\r\n<p>One config, isolated state per workspace. The <code>default</code> workspace cannot be deleted. Use workspaces for non-prod isolation; for prod-grade isolation, prefer separate buckets/accounts per env.</p>\r\n<h3 id=\"count-vs-for-each-the-comparison\"><span class=\"n\">▣</span>count vs for_each — the comparison</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">count — N identical copies</div>\r\n<div class=\"code mini\">resource \"aws_instance\" \"web\" {\r\n  count = 3\r\n  ami   = \"ami-123\"\r\n  tags  = { Name = \"web-${count.index}\" }\r\n}\r\n<span class=\"g\"># addresses: web[0], web[1], web[2]</span></div>\r\n<p><b>Trap:</b> remove <code>count = 3</code> → set to 2 → ALL 3 destroy, 2 fresh create. <b>Don't use for resources with identity.</b></p>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\">for_each — N named copies</div>\r\n<div class=\"code mini\">resource \"aws_instance\" \"web\" {\r\n  for_each = toset([\"ahmed\", \"sara\", \"omar\"])\r\n  ami      = \"ami-123\"\r\n  tags     = { Name = \"web-${each.key}\" }\r\n}\r\n<span class=\"g\"># addresses: web[\"ahmed\"], web[\"sara\"], web[\"omar\"]</span></div>\r\n<p><b>Win:</b> remove \"ahmed\" from the set → only web[\"ahmed\"] destroys. The rest keep their stable keys.</p>\r\n</div>\r\n</div>\r\n<h3 id=\"conditional-attributes-with-for-each\"><span class=\"n\">▣</span>Conditional attributes with for_each</h3>\r\n<div class=\"code\">variable \"create_public_ip\" {\r\n  type    = bool\r\n  default = true\r\n}\r\n\r\nresource \"aws_instance\" \"web\" {\r\n  for_each          = toset([\"a\", \"b\", \"c\"])\r\n  ami               = \"ami-123\"\r\n  instance_type     = each.key == \"a\" ? \"t3.small\" : \"t3.micro\"\r\n  associate_public_ip_address = var.create_public_ip\r\n}</div>\r\n<p>Use <code>each.key</code> and <code>each.value</code> inside the block. <code>for_each</code> accepts a set or a map — set for strings, map for key/value pairs.</p>\r\n\r\n<p>⏭️ <b>Next:</b> Variables in, outputs out — <a href=\"#ch-16\">Outputs</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 18 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 16</div><h1 id=\"outputs-share-export-ci-cd\">📤 Outputs — Share, Export, CI/CD</h1></div><span class=\"hmeta\">🟡 6 MIN · T21</span></div></div>\r\n<p>Variables are inputs. <b>Outputs</b> are exports — values that surface after <code>apply</code> for humans, other modules, and pipelines to consume. Four uses, all in the same <code>outputs</code> block.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 The 4 uses of outputs</span><b>①</b> Display after apply (read with <code>terraform output</code>). <b>②</b> Share between modules (child exposes, parent consumes). <b>③</b> Remote state access via <code>terraform_remote_state</code>. <b>④</b> CI/CD parsing (raw JSON, scripted pipelines).</div>\r\n<h3 id=\"outputs-the-full-anatomy\"><span class=\"n\">▣</span>Outputs — the full anatomy</h3>\r\n<div class=\"code\"># outputs.tf\r\noutput \"vpc_id\" {\r\n  value       = aws_vpc.main.id\r\n  description = \"the VPC ID — pass to other modules\"\r\n  sensitive   = false   <span class=\"g\"># true hides from CLI output</span>\r\n}\r\n\r\noutput \"db_password\" {\r\n  value     = aws_db_instance.main.password\r\n  sensitive = true   <span class=\"g\"># won't print in `terraform output`</span>\r\n}\r\n\r\noutput \"all_subnet_ids\" {\r\n  value = aws_subnet.public[*].id   <span class=\"g\"># list comprehension</span>\r\n}\r\n\r\n# After apply\r\n$ terraform apply\r\n<span class=\"s\">vpc_id = \"vpc-0ab123456\"</span>\r\n<span class=\"s\">all_subnet_ids = [</span>\r\n<span class=\"s\">  \"subnet-0aa...\",</span>\r\n<span class=\"s\">  \"subnet-0bb...\",</span>\r\n<span class=\"s\">  \"subnet-0cc...\",</span>\r\n<span class=\"s\">]</span>\r\n\r\n$ terraform output -raw vpc_id        <span class=\"g\"># no quotes, perfect for scripts</span>\r\nvpc-0ab123456\r\n$ terraform output -json vpc_id     <span class=\"g\"># JSON for CI/CD</span>\r\n{\"vpc_id\":\"vpc-0ab123456\"}</div>\r\n<h3 id=\"sharing-outputs-across-modules\"><span class=\"n\">▣</span>Sharing outputs across modules</h3>\r\n<div class=\"code\"># modules/vpc/outputs.tf\r\noutput \"vpc_id\" { value = aws_vpc.main.id }\r\noutput \"public_subnet_ids\" { value = aws_subnet.public[*].id }\r\n\r\n# root main.tf — consumer\r\nmodule \"vpc\" {\r\n  source = \"./modules/vpc\"\r\n}\r\n\r\nresource \"aws_instance\" \"web\" {\r\n  ami       = \"ami-123\"\r\n  subnet_id = module.vpc.public_subnet_ids[0]   <span class=\"g\"># read module output</span>\r\n}</div>\r\n<p>Modules expose values the same way the root does. Reference any output as <code>module.NAME.OUTPUT</code>. For sharing state between <i>separate</i> Terraform projects (different folders, different teams), use the <code>terraform_remote_state</code> data source.</p>\r\n\r\n<p>⏭️ <b>Next:</b> Day 2 closes. Level 2 opens — <a href=\"#ch-17\">Providers catalog</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 19 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · LEVEL 2 · CH 17</div><h1 id=\"providers-iaas-paas-saas\">🌍 Providers — IaaS / PaaS / SaaS</h1></div><span class=\"hmeta\">🟡 6 MIN · T9 (deep)</span></div></div>\r\n<p>Providers are <b>translators</b>: your HCL speaks <code>resource \"aws_instance\" \"web\" {…}</code>, the provider translates that into the right HTTP call to AWS, GCP, Cloudflare, or GitHub. 3000+ providers exist; you can write your own for in-house systems.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 Three layers of providers</span><b>IaaS</b> (raw infra): AWS, GCP, Azure, Alibaba, DigitalOcean. <b>PaaS</b> (managed platforms): Heroku, Render, Vercel, Supabase. <b>SaaS</b> (third-party APIs): Cloudflare, GitHub, Datadog, PagerDuty, Stripe.</div>\r\n<h3 id=\"the-provider-ecosystem-at-a-glance\"><span class=\"n\">▣</span>The provider ecosystem at a glance</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Layer</th><th>Examples</th><th>What you manage</th></tr>\r\n<tr><td><b>IaaS</b></td><td>AWS, GCP, Azure, Alibaba, OCI, DigitalOcean, Linode</td><td>VMs, networks, storage, databases (raw primitives)</td></tr>\r\n<tr><td><b>PaaS</b></td><td>Heroku, Render, Vercel, Fly.io, Supabase</td><td>Apps, services, managed databases (higher-level)</td></tr>\r\n<tr><td><b>SaaS</b></td><td>Cloudflare, GitHub, GitLab, Datadog, PagerDuty, Stripe</td><td>DNS, repos, monitoring, alerts, billing</td></tr>\r\n<tr><td><b>In-house</b></td><td>your own custom provider (Go SDK)</td><td>your internal platform's API</td></tr>\r\n</table></div>\r\n<h3 id=\"one-apply-three-layers\"><span class=\"n\">▣</span>One apply, three layers</h3>\r\n<div class=\"code\">resource \"aws_s3_bucket\" \"logs\" { bucket = \"study-logs\" }      <span class=\"g\"># IaaS</span>\r\nresource \"github_repository\" \"infra\" {                            <span class=\"g\"># SaaS</span>\r\n  name = \"infra\"\r\n  visibility = \"private\"\r\n}\r\nresource \"cloudflare_record\" \"root\" {                               <span class=\"g\"># SaaS</span>\r\n  zone_id = var.cf_zone\r\n  name    = \"@\"\r\n  value   = aws_s3_bucket.logs.website_endpoint\r\n  type    = \"CNAME\"\r\n}\r\n\r\n$ terraform apply\r\n<span class=\"s\"># one apply, three different APIs called</span></div>\r\n<p>You can call multiple providers in one <code>apply</code>. The dependency graph spans all of them. An AWS bucket URL feeds directly into a Cloudflare DNS record. Second region? <code>provider \"aws\" { alias = \"eu\" }</code>, then <code>provider = aws.eu</code> on the resource.</p>\r\n<h3 id=\"version-constraints-pin-the-right-way\"><span class=\"n\">▣</span>Version constraints — pin the right way</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Operator</th><th>Means</th><th>Example</th><th>Verdict</th></tr>\r\n<tr><td><code>~&gt; 5.0</code></td><td>allow 5.x, block 6.0</td><td>5.1 → 5.9 ok, 6.0 no</td><td>✅ default</td></tr>\r\n<tr><td><code>&gt;= 1.6, &lt; 2.0</code></td><td>range</td><td>safe minimum + cap</td><td>✅ for CLI</td></tr>\r\n<tr><td><code>= 1.9.8</code></td><td>exact</td><td>reproducible</td><td>ok for prod freeze</td></tr>\r\n<tr><td><code>&gt;= 5.0</code> alone</td><td>no cap</td><td>6.0 surprise breaks</td><td>❌ avoid</td></tr>\r\n</table></div>\r\n\r\n<p>⏭️ <b>Next:</b> The escape hatch — <a href=\"#ch-18\">Provisioners</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 20 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · LEVEL 2 · CH 18</div><h1 id=\"provisioners-doctrine-last-resort\">🛠 Provisioners — Doctrine: Last Resort</h1></div><span class=\"hmeta\">🟡 7 MIN · T22</span></div></div>\r\n<p>Provisioners run scripts after resource creation or before destruction. They're the escape hatch when the provider doesn't have a feature — and the doctrine is <b>use them last</b>. user_data, Packer, Ansible cover 95% better.</p>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ The critical caveat</span>Provisioners run <b>ONLY on the resource's first creation</b>. Re-apply with an unchanged resource does NOT re-run them. They re-run only after destroy + recreate. <b>State never knows if the script succeeded</b> — only that Terraform \"tried\". Failed provisioner + existing resource = green plan over a half-built box; recover with <code>taint</code> + re-apply. <code>on_failure = continue</code> is for best-effort logging only.</div>\r\n<h3 id=\"local-exec-vs-remote-exec\"><span class=\"n\">▣</span>local-exec vs remote-exec</h3>\r\n<div class=\"grid2\">\r\n<div class=\"panel\"><div class=\"ptitle\">local-exec (runs on YOUR machine)</div>\r\n<div class=\"code mini\">resource \"aws_instance\" \"web\" {\r\n  ami           = \"ami-123\"\r\n  instance_type = \"t3.micro\"\r\n\r\n  provisioner \"local-exec\" {\r\n    command = \"echo ${self.private_ip} &gt;&gt; deployed.txt\"\r\n    <span class=\"g\"># runs on the machine running Terraform</span>\r\n  }\r\n}</div>\r\n<p>Use cases: register the new instance in your inventory, post to Slack, write to a file. <b>Does not affect the resource itself.</b></p>\r\n</div>\r\n<div class=\"panel\"><div class=\"ptitle\">remote-exec (runs ON the resource)</div>\r\n<div class=\"code mini\">resource \"aws_instance\" \"web\" {\r\n  ami           = \"ami-123\"\r\n  instance_type = \"t3.micro\"\r\n\r\n  connection {\r\n    type        = \"ssh\"\r\n    user        = \"ubuntu\"\r\n    private_key = file(\"~/.ssh/lab.pem\")\r\n    host        = self.public_ip\r\n  }\r\n\r\n  provisioner \"remote-exec\" {\r\n    inline = [\r\n      \"sudo apt-get update -y\",\r\n      \"sudo apt-get install -y nginx\"\r\n    ]\r\n    <span class=\"g\"># runs on the new VM via SSH</span>\r\n  }\r\n}</div>\r\n<p>Use cases: bootstrap the OS. <b>Breaks idempotence</b> if the inline script isn't safe to re-run.</p>\r\n</div>\r\n</div>\r\n<h3 id=\"when-to-use-provisioners-the-doctrine\"><span class=\"n\">▣</span>When to use provisioners (the doctrine)</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Need</th><th>Use this, not a provisioner</th></tr>\r\n<tr><td>Install packages on first boot</td><td><code>user_data</code> / <code>cloud-init</code> (declarative, retryable, in state)</td></tr>\r\n<tr><td>Bake a golden image</td><td>Packer (builds AMI outside Terraform entirely)</td></tr>\r\n<tr><td>Configure the running OS</td><td>Ansible (idempotent modules, no SSH key in Terraform)</td></tr>\r\n<tr><td>External side effect (register, post to Slack)</td><td><code>local-exec</code> is fine</td></tr>\r\n<tr><td>Something nothing else can do</td><td><code>remote-exec</code> as last resort</td></tr>\r\n</table></div>\r\n<div class=\"mark m-fun\"><span class=\"tag\">😄 The classic mistake</span>You provision an EC2, then <code>remote-exec</code> runs <code>apt install nginx</code> on first boot. Plan looks great. Then next week you change the instance type, apply, and... nginx is <b>still installed</b> (provisioner doesn't re-run). It works because you got lucky. <b>The cure:</b> bake nginx into a Packer AMI and let Terraform deploy images, not scripts.</div>\r\n\r\n<p>⏭️ <b>Next:</b> The Lego brick — <a href=\"#ch-19\">Modules</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 21 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div>\r\n<div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · LEVEL 2 · CH 19</div><h1 id=\"modules-package-version-reuse\">🧱 Modules — Package, Version, Reuse</h1></div><span class=\"hmeta\">🟡 6 MIN · T23</span></div></div>\r\n<p>A module is a <b>container for multiple resources used together</b>. Every Terraform configuration is itself a module (the root module). Modules can call other modules — that's reuse, packaging, consistent patterns across teams.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 Every config is a module</span>You're always in a module. The <b>root module</b> = where you run <code>terraform apply</code>. <b>Child modules</b> = folders you call via <code>module \"x\" { source = \"...\" }</code>. <b>Published modules</b> = on the registry, versioned, immutable.</div>\r\n<h3 id=\"module-structure\"><span class=\"n\">▣</span>Module structure</h3>\r\n<div class=\"code\">modules/ec2/\r\n  main.tf       <span class=\"g\"># resources; no hardcoded values; uses variables</span>\r\n  variables.tf  <span class=\"g\"># all inputs + validations</span>\r\n  outputs.tf    <span class=\"g\"># all exports; never expose secrets unmarked</span>\r\n  versions.tf   <span class=\"g\"># required_version, required_providers</span></div>\r\n<h3 id=\"call-read-outputs\"><span class=\"n\">▣</span>Call + read outputs</h3>\r\n<div class=\"code\"># modules/ec2/main.tf\r\nresource \"aws_instance\" \"this\" {\r\n  count         = var.count\r\n  ami           = var.ami\r\n  instance_type = var.instance_type\r\n  tags          = merge(var.tags, { Module = \"ec2\", Index = count.index })\r\n}\r\n\r\noutput \"instance_ids\" { value = aws_instance.this[*].id }\r\n\r\n# root: call + read outputs\r\nmodule \"ec2_cluster\" {\r\n  source        = \"./modules/ec2\"\r\n  count         = 3\r\n  ami           = data.aws_ami.ubuntu.id\r\n  instance_type = var.env == \"prod\" ? \"t3.small\" : \"t3.micro\"\r\n}\r\n\r\nresource \"aws_lb_target_group_attachment\" \"example\" {\r\n  target_group_arn = aws_lb_target_group.app.arn\r\n  target_id        = module.ec2_cluster.instance_ids[0]\r\n}</div>\r\n<div class=\"table-scroll\"><table><tr><th>Source</th><th>Example</th><th>Versioning</th></tr>\r\n<tr><td>Registry</td><td><code>\"terraform-aws-modules/vpc/aws\"</code></td><td>✅ enforced</td></tr>\r\n<tr><td>Git</td><td><code>\"github.com/org/repo//modules/ec2?ref=v1.2.0\"</code></td><td>manual pin</td></tr>\r\n<tr><td>Local</td><td><code>\"./modules/ec2\"</code></td><td>n/a</td></tr>\r\n</table></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠️ Provider inheritance</span>Reusable modules = <b>no provider block</b> (accepts the caller's). <code>module \"vpc\" { providers = { aws = aws.eu } ... }</code> passes a specific provider alias.</div>\r\n\r\n<p>⏭️ <b>Next:</b> The CAPSTONE — <a href=\"#lab-1\">Lab 1</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 22 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · CAPSTONE</div><h1 id=\"lab-1-full-build-chain\">⭐ Lab 1 — Full Build Chain</h1></div><span class=\"hmeta\">🟠 12 MIN · T24</span></div></div>\r\n<p>Stitches every chapter: <b>Provider → VPC → Subnets → Instances → SG → Outputs → Provisioner → Destroy</b>. Tab 2 builds, Tab 1 observes.</p>\r\n<h3 id=\"the-full-main-tf-8-resources-one-file\"><span class=\"n\">▣</span>The full main.tf (8 resources, one file)</h3>\r\n<div class=\"code\">terraform {\r\n  required_providers { aws = { source = \"hashicorp/aws\", version = \"~&gt; 5.0\" } }\r\n}\r\n\r\nprovider \"aws\" {\r\n  region = \"us-east-1\"\r\n  access_key = \"test\"  secret_key = \"test\"     <span class=\"g\"># Floci: dummy creds; AWS: delete these</span>\r\n  skip_credentials_validation = true\r\n  skip_metadata_api_check     = true\r\n  skip_requesting_account_id  = true\r\n  endpoints { ec2 = \"http://localhost:4566\" }    <span class=\"g\"># Floci only; delete for AWS</span>\r\n}\r\n\r\nresource \"aws_vpc\" \"main\" { cidr_block = \"10.0.0.0/16\" tags = { Name = \"capstone\" } }\r\n\r\nresource \"aws_subnet\" \"a\" { vpc_id = aws_vpc.main.id  cidr_block = \"10.0.1.0/24\"  availability_zone = \"us-east-1a\" }\r\nresource \"aws_subnet\" \"b\" { vpc_id = aws_vpc.main.id  cidr_block = \"10.0.2.0/24\"  availability_zone = \"us-east-1b\" }\r\n\r\nresource \"aws_security_group\" \"web\" {\r\n  name = \"web-sg\"\r\n  vpc_id = aws_vpc.main.id\r\n  ingress { from_port = 443  to_port = 443  protocol = \"tcp\"  cidr_blocks = [\"0.0.0.0/0\"] }\r\n  egress  { from_port = 0    to_port = 0    protocol = \"-1\"   cidr_blocks = [\"0.0.0.0/0\"] }\r\n}\r\n\r\nresource \"aws_instance\" \"web\" {\r\n  for_each               = toset([\"a1\",\"a2\",\"b1\",\"b2\"])\r\n  ami                    = \"ami-0c55b159cbfafe1f0\"\r\n  instance_type          = \"t3.micro\"\r\n  subnet_id              = startsWith(each.key, \"a\") ? aws_subnet.a.id : aws_subnet.b.id\r\n  vpc_security_group_ids = [aws_security_group.web.id]\r\n  tags                   = { Name = \"web-${each.key}\" }\r\n}\r\n\r\noutput \"ips\" {\r\n  value = { for k, inst in aws_instance.web : k =&gt; inst.private_ip }\r\n}\r\n\r\nresource \"null_resource\" \"log_ips\" {\r\n  triggers = { ids = jsonencode(aws_instance.web) }\r\n  provisioner \"local-exec\" {\r\n    command = \"echo 'instances ready:' &gt;&gt; deployed.txt\"\r\n  }\r\n}</div>\r\n<h3 id=\"two-terminal-execution\"><span class=\"n\">▣</span>Two-terminal execution</h3>\r\n<div class=\"grid2\">\r\n<div class=\"termwin\"><div class=\"termhead th-obs\">👀 TAB 1 · OBSERVE</div><div class=\"termbody\">floci start\r\neval \"$(floci env)\"\r\n<span class=\"p\">watch aws ec2 describe-instances</span>   <span class=\"g\"># watch instances appear</span>\r\n<span class=\"p\">watch aws ec2 describe-vpcs</span>        <span class=\"g\"># watch VPCs</span></div></div>\r\n<div class=\"termwin\"><div class=\"termhead th-ctl\">⚙️ TAB 2 · CONTROL</div><div class=\"termbody\">cd ~/lab-capstone\r\n<span class=\"p\">terraform init</span>\r\n<span class=\"p\">terraform plan -out=tfplan</span>\r\n<span class=\"p\">terraform apply tfplan</span>\r\n<span class=\"p\">terraform output -json ips</span>   <span class=\"g\"># → {\"a1\":\"10.0.1.11\",...}</span>\r\n<span class=\"p\">terraform destroy -auto-approve</span></div></div>\r\n</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 What this proved</span>You built the entire chain: provider auth → VPC → 2 subnets → 4 instances via for_each → security group → outputs JSON → local-exec provisioner → full teardown. <b>The same code runs against real AWS</b> by deleting the Floci <code>endpoints</code> + <code>skip_*</code> lines and changing auth to SSO/profile. That's the whole IaC story in 8 resources.</div>\r\n<p>⏭️ <b>Next:</b> The review — <a href=\"#cheat\">Cheat · Quiz · Glossary · Resources</a>.</p>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 23 —</span><span><a href=\"#toc\">TOC</a> prev | next</span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">FINALE</div><h1 id=\"cheat-sheet-quiz-glossary-resources\">📋 Cheat Sheet · Quiz · Glossary · Resources</h1></div><span class=\"hmeta\">🏁 FINALE</span></div></div>\r\n<p>The story in one page: commands, quiz, glossary, resources. Five minutes of review before the interview.</p>\r\n<h3 id=\"cheat-sheet-the-14-commands\"><span class=\"n\">▣</span>Cheat sheet — the 14 commands</h3>\r\n<div class=\"table-scroll\"><table><tr><th>Command</th><th>What it does</th></tr>\r\n<tr><td><code>terraform init</code></td><td>install providers + wire backend</td></tr>\r\n<tr><td><code>terraform fmt</code></td><td>canonical formatting</td></tr>\r\n<tr><td><code>terraform validate</code></td><td>syntax check (offline)</td></tr>\r\n<tr><td><code>terraform plan -out=tfplan</code></td><td>preview diff, save to file</td></tr>\r\n<tr><td><code>terraform apply tfplan</code></td><td>apply EXACTLY the reviewed plan</td></tr>\r\n<tr><td><code>terraform destroy</code></td><td>tear it all down</td></tr>\r\n<tr><td><code>terraform output -raw &lt;name&gt;</code></td><td>read an output value</td></tr>\r\n<tr><td><code>terraform state list / show / mv / rm</code></td><td>operate on state without recreating</td></tr>\r\n<tr><td><code>terraform import &lt;addr&gt; &lt;id&gt;</code></td><td>adopt existing infra</td></tr>\r\n<tr><td><code>terraform force-unlock &lt;ID&gt;</code></td><td>release a stuck lock (DANGEROUS)</td></tr>\r\n<tr><td><code>terraform workspace &lt;list|new|select&gt;</code></td><td>state isolation per env</td></tr>\r\n<tr><td><code>terraform graph | dot -Tsvg</code></td><td>visualize the dependency graph</td></tr>\r\n</table></div>\r\n<h3 id=\"quiz-8-questions\"><span class=\"n\">▣</span>Quiz — 8 questions</h3>\r\n<div class=\"grid2\">\r\n<div class=\"qz\"><span class=\"qn\">1.</span> What does <code>terraform init</code> do? (jobs 1 &amp; 2)</div>\r\n<div class=\"qz\"><span class=\"qn\">2.</span> Idempotence in one sentence.</div>\r\n<div class=\"qz\"><span class=\"qn\">3.</span> The 3 states. What does plan compare?</div>\r\n<div class=\"qz\"><span class=\"qn\">4.</span> What do <code>+</code> / <code>~</code> / <code>-/+</code> / <code>-</code> mean?</div>\r\n<div class=\"qz\"><span class=\"qn\">5.</span> Why no keys in <code>.tf</code>? (3 reasons)</div>\r\n<div class=\"qz\"><span class=\"qn\">6.</span> Resource vs data source.</div>\r\n<div class=\"qz\"><span class=\"qn\">7.</span> Variable precedence: lowest to highest?</div>\r\n<div class=\"qz\"><span class=\"qn\">8.</span> count vs for_each — which, and why?</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 Quick answers (open in your notes)</span><b>A1.</b> Install providers + wire backend. <b>A2.</b> apply twice = apply once. <b>A3.</b> Desired vs Known vs Real. <b>A4.</b> +/~/−/+create or update or destroy or recreate. <b>A5.</b> leaks to state+git+rotation cost. <b>A6.</b> managed lifecycle vs read-only lookup. <b>A7.</b> defaults &lt; tfvars &lt; -var &lt; TF_VAR_*. <b>A8.</b> for_each (stable keys on remove).</div>\r\n</div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">FINALE</div><h1 id=\"glossary-resources\">Glossary + Resources</h1></div><span class=\"hmeta\">📖 PAGE 2</span></div></div><h3 id=\"glossary-20-terms\"><span class=\"n\">▣</span>Glossary — 20 terms</h3>\r\n<div class=\"grid2\">\r\n<div class=\"glos\"><b>apply</b> — executes the planned changes.</div>\r\n<div class=\"glos\"><b>backend</b> — where <code>terraform.tfstate</code> lives.</div>\r\n<div class=\"glos\"><b>core</b> — Terraform's brain: parses, graphs, plans, calls plugins.</div>\r\n<div class=\"glos\"><b>data source</b> — read-only lookup, no lifecycle.</div>\r\n<div class=\"glos\"><b>desired state</b> — what your <code>.tf</code> declares.</div>\r\n<div class=\"glos\"><b>drift</b> — reality diverged from code.</div>\r\n<div class=\"glos\"><b>HCL</b> — HashiCorp Configuration Language.</div>\r\n<div class=\"glos\"><b>idempotence</b> — apply twice = apply once.</div>\r\n<div class=\"glos\"><b>IGW</b> — Internet Gateway.</div>\r\n<div class=\"glos\"><b>known state</b> — what <code>terraform.tfstate</code> records.</div>\r\n<div class=\"glos\"><b>lock table</b> — DynamoDB row per backend key. Mutex for state writes.</div>\r\n<div class=\"glos\"><b>module</b> — reusable, parameterized folder.</div>\r\n<div class=\"glos\"><b>NAT Gateway</b> — managed, ~$32/mo+data, AZ-bound.</div>\r\n<div class=\"glos\"><b>OIDC</b> — short-lived token CI assumes into IAM roles.</div>\r\n<div class=\"glos\"><b>plan</b> — the diff: +/~/−.</div>\r\n<div class=\"glos\"><b>provider</b> — plugin that translates HCL to API calls.</div>\r\n<div class=\"glos\"><b>provisioner</b> — escape hatch to run scripts. Last resort only.</div>\r\n<div class=\"glos\"><b>real state</b> — what the cloud looks like (after refresh).</div>\r\n<div class=\"glos\"><b>SSO</b> — temporary credentials, no long-lived keys.</div>\r\n<div class=\"glos\"><b>workspace</b> — state isolation per env in one config.</div>\r\n</div>\r\n<h3 id=\"resources-keep-these-handy\"><span class=\"n\">▣</span>Resources — keep these handy</h3>\r\n<div class=\"resbox\">\r\n<b>Course deck (this book is built on it):</b> Eng. Mohamed Magdy — Terraform Level 1 + 2<br /><br />\r\n<b>Official:</b> <a href=\"https://registry.terraform.io\" target=\"_blank\" rel=\"noopener noreferrer\">registry.terraform.io</a> · <a href=\"https://developer.hashicorp.com/terraform\" target=\"_blank\" rel=\"noopener noreferrer\">developer.hashicorp.com/terraform</a> · <a href=\"https://github.com/hashicorp/terraform\" target=\"_blank\" rel=\"noopener noreferrer\">github.com/hashicorp/terraform</a><br />\r\n<b>Learn:</b> <a href=\"https://github.com/hashicorp/learn-terraform\" target=\"_blank\" rel=\"noopener noreferrer\">learn-terraform</a> (free labs) · <a href=\"https://discuss.hashicorp.com/c/terraform-core/\" target=\"_blank\" rel=\"noopener noreferrer\">discuss.hashicorp.com</a> (forum)<br />\r\n<b>Local emulator:</b> <a href=\"https://floci.io\" target=\"_blank\" rel=\"noopener noreferrer\">floci.io</a> (Floci — free MIT, port 4566)<br />\r\n<b>Exam:</b> HashiCorp Certified — Terraform Associate (covers most of this book)\r\n</div>\r\n<div class=\"folio\"><span>Terraform · Vol 1</span><span class=\"fnum\">— Page 24 —</span><span><a href=\"#toc\">TOC</a></span></div></div>","toc":[{"id":"terraformlevel-1-2","text":"TerraformLevel 1 + 2","level":1},{"id":"map-of-the-book","text":"🗺️ Map of the Book","level":1},{"id":"how-to-read-this-book","text":"▣How to read this book","level":3},{"id":"the-route-one-page-whole-book","text":"🗺️ The Route — One Page, Whole Book","level":1},{"id":"what-is-infrastructure-as-code","text":"📐 What is Infrastructure as Code?","level":1},{"id":"the-5-step-loop-memorize","text":"▣The 5-step loop (memorize)","level":3},{"id":"why-it-exists-a-real-story","text":"▣Why it exists — a real story","level":3},{"id":"what-is-terraform-the-6-pillars-of-why","text":"💎 What is Terraform + The 6 Pillars of Why","level":1},{"id":"the-6-pillars","text":"▣The 6 pillars","level":3},{"id":"how-terraform-works-core-vs-plugins","text":"🧠 How Terraform Works — Core vs Plugins","level":1},{"id":"what-core-does-brain","text":"▣What core does (brain)","level":3},{"id":"resource-vs-data-source-the-critical-distinction","text":"▣Resource vs data source (the critical distinction)","level":3},{"id":"aws-provider-three-auth-patterns","text":"🔑 AWS Provider — Three Auth Patterns","level":1},{"id":"auth-priority-order-first-hit-wins","text":"▣Auth priority order (first hit wins)","level":3},{"id":"three-patterns-you-ll-use","text":"▣Three patterns you'll use","level":3},{"id":"safety-belt","text":"▣Safety belt","level":3},{"id":"your-first-resource-aws-vpc","text":"🧱 Your First Resource — aws_vpc","level":1},{"id":"resource-block-anatomy-memorize","text":"▣Resource block anatomy (memorize)","level":3},{"id":"the-pro-pattern-registry-module-beats-hand-rolled","text":"▣The pro pattern — registry module beats hand-rolled","level":3},{"id":"subnets-route-tables-igw-nat","text":"🌐 Subnets · Route Tables · IGW · NAT","level":1},{"id":"the-4-resources-you-touch-every-day","text":"▣The 4 resources you touch every day","level":3},{"id":"terraform-init-what-it-really-does","text":"🔌 terraform init — What It Really Does","level":1},{"id":"job-1-always-install-providers-modules","text":"▣Job 1 (always) — install providers + modules","level":3},{"id":"job-2-only-with-a-backend-block-wire-up-state-storage","text":"▣Job 2 (only with a backend block) — wire up state storage","level":3},{"id":"the-gitignore-canon","text":"▣The .gitignore canon","level":3},{"id":"plan-apply-tfstate-the-core-loop","text":"🔁 plan · apply · tfstate — The Core Loop","level":1},{"id":"the-7-command-loop-every-session","text":"▣The 7-command loop (every session)","level":3},{"id":"what-tfstate-actually-contains","text":"▣What tfstate actually contains","level":3},{"id":"the-3-state-model-code-state-reality","text":"📒 The 3-State Model — code · state · reality","level":1},{"id":"reading-a-plan-output","text":"▣Reading a plan output","level":3},{"id":"state-risks-amp-remote-backend-s3-dynamodb","text":"☁️ State Risks &amp; Remote Backend (S3 + DynamoDB)","level":1},{"id":"backend-anatomy","text":"▣Backend anatomy","level":3},{"id":"bootstrap-chicken-and-egg","text":"▣Bootstrap (chicken-and-egg)","level":3},{"id":"how-locking-works-3-steps","text":"▣How locking works (3 steps)","level":3},{"id":"state-locking-the-mutex-explained","text":"🔒 State Locking — The Mutex Explained","level":1},{"id":"what-the-lock-error-looks-like","text":"▣What the lock error looks like","level":3},{"id":"force-unlock-the-danger-zone","text":"▣Force-unlock — the danger zone","level":3},{"id":"state-subcommands-cli-extras","text":"🔧 State Subcommands + CLI Extras","level":1},{"id":"state-subcommands-5-essential","text":"▣State subcommands (5 essential)","level":3},{"id":"the-other-clis-you-ll-use","text":"▣The other CLIs you'll use","level":3},{"id":"fmt-amp-destroy-canon-format-safe-teardown","text":"🧹 fmt &amp; destroy — Canon Format, Safe Teardown","level":1},{"id":"fmt-before-after","text":"▣fmt before → after","level":3},{"id":"destroy-the-teardown-pattern","text":"▣destroy — the teardown pattern","level":3},{"id":"destroy-in-the-lab-vs-prod","text":"▣destroy in the lab vs prod","level":3},{"id":"variables-amp-the-precedence-ladder","text":"🎚️ Variables &amp; the Precedence Ladder","level":1},{"id":"variables-the-full-anatomy","text":"▣Variables — the full anatomy","level":3},{"id":"the-4-ways-to-pass-variables","text":"▣The 4 ways to pass variables","level":3},{"id":"workspaces-amp-advanced-hcl-count-for-each","text":"🗂️ Workspaces &amp; Advanced HCL (count · for_each)","level":1},{"id":"workspaces-same-code-isolated-state","text":"▣Workspaces — same code, isolated state","level":3},{"id":"count-vs-for-each-the-comparison","text":"▣count vs for_each — the comparison","level":3},{"id":"conditional-attributes-with-for-each","text":"▣Conditional attributes with for_each","level":3},{"id":"outputs-share-export-ci-cd","text":"📤 Outputs — Share, Export, CI/CD","level":1},{"id":"outputs-the-full-anatomy","text":"▣Outputs — the full anatomy","level":3},{"id":"sharing-outputs-across-modules","text":"▣Sharing outputs across modules","level":3},{"id":"providers-iaas-paas-saas","text":"🌍 Providers — IaaS / PaaS / SaaS","level":1},{"id":"the-provider-ecosystem-at-a-glance","text":"▣The provider ecosystem at a glance","level":3},{"id":"one-apply-three-layers","text":"▣One apply, three layers","level":3},{"id":"version-constraints-pin-the-right-way","text":"▣Version constraints — pin the right way","level":3},{"id":"provisioners-doctrine-last-resort","text":"🛠 Provisioners — Doctrine: Last Resort","level":1},{"id":"local-exec-vs-remote-exec","text":"▣local-exec vs remote-exec","level":3},{"id":"when-to-use-provisioners-the-doctrine","text":"▣When to use provisioners (the doctrine)","level":3},{"id":"modules-package-version-reuse","text":"🧱 Modules — Package, Version, Reuse","level":1},{"id":"module-structure","text":"▣Module structure","level":3},{"id":"call-read-outputs","text":"▣Call + read outputs","level":3},{"id":"lab-1-full-build-chain","text":"⭐ Lab 1 — Full Build Chain","level":1},{"id":"the-full-main-tf-8-resources-one-file","text":"▣The full main.tf (8 resources, one file)","level":3},{"id":"two-terminal-execution","text":"▣Two-terminal execution","level":3},{"id":"cheat-sheet-quiz-glossary-resources","text":"📋 Cheat Sheet · Quiz · Glossary · Resources","level":1},{"id":"cheat-sheet-the-14-commands","text":"▣Cheat sheet — the 14 commands","level":3},{"id":"quiz-8-questions","text":"▣Quiz — 8 questions","level":3},{"id":"glossary-resources","text":"Glossary + Resources","level":1},{"id":"glossary-20-terms","text":"▣Glossary — 20 terms","level":3},{"id":"resources-keep-these-handy","text":"▣Resources — keep these handy","level":3}],"words":7623,"assets":[]};